      "path": "cordis.patch.yml",
      "content": "# DeepSeek Harness TUI profile layer. It adds the Host capabilities shared\n# with Web, a network-free Connection carrier, and the terminal startup bridge.\n# No Web server, browser loader, or React package is mounted.\n\n- id: system-prompt\n  config:\n    personaPrefix: >-\n      You are a coding agent powered by the {{model}} model. Your working directory is {{cwd}}.\n\n- id: hmr\n  disabled: true\n\n# The base disables full-text search by default. `/resume <query>` keeps using\n# the official search service, opening its derived index only when requested.\n# Config replacement is whole-row, so retain the explicit in-memory path.\n- id: session-query-sqlite\n  config:\n    path: ':memory:'\n    openAt: first-search\n\n- id: tools\n  config:\n    mode: !!js process.env.DSH_TOOLS_MODE\n\n# The terminal is a Surface over the same multi-session Agent plane as Web.\n# Model-facing rows therefore live in each Agent Preset, while process-wide\n# registries, projections, commands, and API services remain in the Host.\n- id: tool-bash\n  disabled: true\n\n- id: tool-pwsh\n  disabled: true\n\n- id: tool-jobs\n  disabled: true\n\n- id: tool-fs\n  disabled: true\n\n- id: tool-fs-search\n  disabled: true\n\n- id: tool-str-replace-editor\n  disabled: true\n\n- id: skill-filesystem\n  disabled: true\n\n- id: tool-skill\n  disabled: true\n\n- id: command-goal\n  disabled: true\n\n- id: tool-goal\n  disabled: true\n\n- id: plan-mode\n  disabled: true\n\n- id: compaction-basic\n  disabled: true\n\n- id: command-compact\n  disabled: true\n\n- id: tool-result-pruner\n  disabled: true\n\n- id: tool-subagent-control\n  disabled: true\n\n- id: tool-subagent-list-agents\n  disabled: true\n\n- id: tool-subagent\n  disabled: true\n\n- id: tool-subagent-fork\n  disabled: true\n\n- id: workflow-ptc\n  disabled: true\n\n- id: tool-workflow\n  disabled: true\n\n- id: tool-ralph\n  disabled: true\n\n- id: agent-instructions\n  disabled: true\n\n- id: tool-todo\n  disabled: true\n\n- id: tool-web\n  disabled: true\n\n- insert:\n    - id: subagent-model-selection-settings\n      name: '@deepseek-ai/dsh-tool-subagent/model-selection-settings'\n\n    - id: agent-preset-registry\n      name: '@deepseek-ai/dsh-agent-preset-registry'\n      config:\n        default: standard\n\n    - id: ptc-runtime\n      name: '@deepseek-ai/dsh-ptc-runtime-node'\n\n    - id: message-feedback\n      name: '@deepseek-ai/dsh-message-feedback'\n      config:\n        maxNoteBytes: 8192\n\n    # Register the official Harness-owned zh/en preference. SeekTTY reads and\n    # writes this same locale.preference value instead of persisting a second\n    # terminal-only language setting.\n    - id: locale\n      name: '@deepseek-ai/dsh-client-locale'\n\n    - id: workspace\n      name: '@deepseek-ai/dsh-workspace'\n\n    - id: session-stats\n      name: '@deepseek-ai/dsh-session-stats'\n\n    # Session Controller uses the shared directory-picker seam. The TUI composes the\n    # platform-neutral browse backend so future `/workspace` overlays can list\n    # paths without opening a GUI dialog or mounting Web transport.\n    - id: directory-picker\n      name: '@deepseek-ai/dsh-host-directory-picker-browse'\n\n    - id: plugin-inventory\n      name: '@deepseek-ai/dsh-host-plugin-inventory'\n\n    # Extension registry for discovery Providers contributed by Harness\n    # Bundles. Provider sources stay read-only in the TUI; install state still\n    # belongs exclusively to the native Profile/pnpm manager.\n    - id: tui-marketplace-providers\n      name: 'seektty/marketplace-provider'\n\n    - id: job-controller\n      name: '@deepseek-ai/dsh-api-job-controller'\n\n    - id: session-controller\n      name: '@deepseek-ai/dsh-api-session-controller'\n\n    - id: file-upload\n      name: '@deepseek-ai/dsh-client-file-upload'\n\n    - id: session-reference\n      name: '@deepseek-ai/dsh-session-reference'\n\n    - id: file-reference-local\n      name: '@deepseek-ai/dsh-file-reference-local'\n\n    - id: settings-controller\n      name: '@deepseek-ai/dsh-api-settings-controller'\n\n    - id: workspace-controller\n      name: '@deepseek-ai/dsh-api-workspace-controller'\n\n    # Ordinary published Host file service; owns scope lookup, bounded reads and\n    # native metadata changes. No Web Client or filesystem provider is mounted.\n    - id: workspace-files\n      name: '@deepseek-ai/dsh-api-workspace-files'\n\n    - id: cordis-host-runner\n      name: '@deepseek-ai/dsh-cordis-host-runner'\n\n    - id: connection\n      name: 'seektty/in-process'\n\n    - id: api-remotes\n      name: '@deepseek-ai/dsh-api-remotes'\n\n    - id: tui-startup\n      name: 'seektty/startup'\n\n    - id: tui-runner\n      name: 'seektty'\n\n# Agent preset standard: one `@deepseek-ai/dsh-agent-preset` declaration inserted\n# after the web patch. Edits saved from the Web editor override this row's\n# `config.plugins` by id from the profile patch.\n- insert:\n    - id: preset-standard\n      name: '@deepseek-ai/dsh-agent-preset'\n      config:\n        id: standard\n        order: 1\n        plugins:\n          - id: persona\n            name: '@deepseek-ai/dsh-persona'\n            config:\n              suffix: Your working directory is {{cwd}}.\n              prefix: You are a coding agent powered by the {{model}} model.\n          - id: agent-instructions\n            name: '@deepseek-ai/dsh-agent-instructions'\n            config:\n              maxBytes: 65536\n          - id: tool-bash\n            name: '@deepseek-ai/dsh-tool-bash'\n            disabled: !!js process.platform === 'win32'\n          - id: tool-pwsh\n            name: '@deepseek-ai/dsh-tool-pwsh'\n            disabled: !!js process.platform !== 'win32'\n          - id: tool-fs\n            name: '@deepseek-ai/dsh-tool-fs'\n          - id: tool-fs-search\n            name: '@deepseek-ai/dsh-tool-fs-search'\n            config:\n              sampleOverCapGlobResults: false\n          - id: tool-jobs\n            name: '@deepseek-ai/dsh-tool-jobs'\n          - id: skill-filesystem\n            name: '@deepseek-ai/dsh-skill-filesystem'\n          - id: tool-skill\n            name: '@deepseek-ai/dsh-tool-skill'\n          - id: command-goal\n            name: '@deepseek-ai/dsh-command-goal'\n          - id: tool-goal\n            name: '@deepseek-ai/dsh-tool-goal'\n          - id: planning\n            name: cordis:group\n            group: true\n            isolate:\n              planMode: true\n            config:\n              - id: plan-mode\n                name: '@deepseek-ai/dsh-plan-mode'\n                config:\n                  section: |\n                    You are in plan mode. Stay in plan mode until exit_plan_mode succeeds or the user switches the session mode. Imperative language to implement changes means plan the implementation, not execute it. A user's conversational agreement — including an answer confirming something you asked — approves nothing and does not end plan mode; fold the confirmed decision into the plan and submit it through exit_plan_mode.\n\n                    Explore first. Use non-mutating reads, searches, static analysis, and checks to ground the plan in the actual repository. Do not edit or write files, change configuration, run formatters or code generation that rewrites tracked files, commit, or otherwise carry out the plan. Prefer existing functions and patterns over new machinery.\n\n                    The tool catalog stays the same across modes for request-cache stability. These plan-mode rules override any later tool description or guidance that suggests using mutation tools; those tools remain listed to keep the tool catalog unchanged. Do not use todo_write to track this planning phase: it tracks implementation after an approved plan, while the plan itself belongs in exit_plan_mode.\n\n                    Resolve discoverable facts by inspection. Use ask_user_question only for user-owned choices or material ambiguity that inspection cannot answer. Do not ask the user where code lives or how current behavior works when you can find out.\n\n                    Make the plan decision-complete: state the goal and success criteria; group implementation changes by subsystem; identify public API, schema, and data-flow changes; cover edge cases, failure modes, tests, acceptance criteria, and explicit assumptions. Keep it concise enough to review but detailed enough that another engineer can implement it without making design decisions.\n\n                    When ready, call exit_plan_mode with the complete plan markdown, starting with a # title. Make exit_plan_mode the only and final tool call in that assistant response: it presents the plan for approval, and implementation begins only in a later step after approval. Do not paste the final plan as a plain reply or ask \"should I proceed?\" through prose or ask_user_question. If review rejects it, incorporate the feedback and present again. If the review channel is unavailable or aborted, stay in plan mode and ask the user to switch modes manually; do not proceed with implementation.\n          - id: compaction\n            name: cordis:group\n            group: true\n            isolate:\n              compaction: true\n              toolResultPruner: true\n            config:\n              - id: compaction-basic\n                name: '@deepseek-ai/dsh-compaction-basic'\n              - id: command-compact\n                name: '@deepseek-ai/dsh-command-compact'\n              - id: tool-result-pruner\n                name: '@deepseek-ai/dsh-compaction-tool-result-pruner'\n                config:\n                  thresholdChars: 8192\n                  headChars: 4096\n                  tailChars: 1024\n          - id: delegation\n            name: cordis:group\n            group: true\n            isolate:\n              workflowEngine: true\n            config:\n              - id: tool-subagent-control\n                name: '@deepseek-ai/dsh-tool-subagent-control'\n              - id: tool-subagent-list-agents\n                name: '@deepseek-ai/dsh-tool-subagent-control/list-agents'\n              - id: tool-subagent\n                name: '@deepseek-ai/dsh-tool-subagent'\n                config:\n                  provider: spawn\n                  toolName: subagent\n                  modelSelectionSettings: true\n                  backgroundMode: continuable\n              - id: tool-subagent-fork\n                name: '@deepseek-ai/dsh-tool-subagent'\n                config:\n                  provider: fork\n                  toolName: subagent_fork\n                  backgroundMode: continuable\n              - id: tool-subagent-codex\n                name: '@deepseek-ai/dsh-tool-subagent'\n                disabled: true\n                config:\n                  provider: codex\n                  toolName: subagent_codex\n                  backgroundMode: one-shot\n                  maxDepth: provider-managed\n              - id: tool-subagent-claude-code\n                name: '@deepseek-ai/dsh-tool-subagent'\n                disabled: true\n                config:\n                  provider: claude-code\n                  toolName: subagent_claude_code\n                  backgroundMode: one-shot\n                  maxDepth: provider-managed\n              - id: workflow-ptc\n                name: '@deepseek-ai/dsh-workflow-ptc'\n                config:\n                  provider: spawn\n              - id: tool-workflow\n                name: '@deepseek-ai/dsh-tool-workflow'\n              - id: tool-ralph\n                name: '@deepseek-ai/dsh-tool-ralph'\n                disabled: true\n                config:\n                  subagentProvider: spawn\n                  maxRounds: 64\n          - id: tool-ask-user\n            name: '@deepseek-ai/dsh-tool-ask-user'\n          - id: tool-todo\n            name: '@deepseek-ai/dsh-tool-todo'\n            config:\n              allowParallelInProgress: true\n          - id: tool-web\n            name: '@deepseek-ai/dsh-tool-web'\n            config:\n              fetch: true\n              searchTimeoutMs: 60000\n          - id: present\n            name: '@deepseek-ai/dsh-tool-present'\n          - id: tool-plugin-manager\n            name: '@deepseek-ai/dsh-plugin-manager/tools'\n            disabled: true\n\n# Agent preset minimal: one `@deepseek-ai/dsh-agent-preset` declaration inserted\n# after the web patch. Edits saved from the Web editor override this row's\n# `config.plugins` by id from the profile patch.\n- insert:\n    - id: preset-minimal\n      name: '@deepseek-ai/dsh-agent-preset'\n      config:\n        id: minimal\n        order: 3\n        plugins:\n          - id: persona\n            name: '@deepseek-ai/dsh-persona'\n            config:\n              prefix: You are a helpful software engineer assistant.\n              complete: true\n              includeRuntimeContext: false\n          - id: persistent-shell\n            name: cordis:group\n            group: true\n            isolate:\n              terminals: true\n            config:\n              - id: pty\n                name: '@deepseek-ai/dsh-terminal'\n              - id: terminal-bash\n                name: '@deepseek-ai/dsh-terminal-bash'\n                disabled: !!js process.platform === 'win32'\n                config:\n                  timeoutMs: 300000\n              - id: persistent-bash\n                name: '@deepseek-ai/dsh-tool-bash-persistent'\n                disabled: !!js process.platform === 'win32'\n                config:\n                  timeoutMs: 300000\n                  description: |-\n                    Run commands in a bash shell\n                    * When invoking this tool, the contents of the \"command\" parameter does NOT need to be XML-escaped.\n                    * Network access depends on the task environment. Prefer configured mirrors/proxies when they are available.\n                    * State is persistent across command calls and discussions with the user.\n                    * To inspect a particular line range of a file, e.g. lines 10-25, try 'sed -n 10,25p /path/to/the/file'.\n                    * Please avoid commands that may produce a very large amount of output.\n                    * Please run long lived commands in the background, e.g. 'sleep 10 &' or start a server in the background.\n              - id: terminal-pwsh\n                name: '@deepseek-ai/dsh-terminal-bash'\n                disabled: !!js process.platform !== 'win32'\n                config:\n                  shellDialect: pwsh\n                  timeoutMs: 300000\n              - id: persistent-pwsh\n                name: '@deepseek-ai/dsh-tool-pwsh-persistent'\n                disabled: !!js process.platform !== 'win32'\n                config:\n                  timeoutMs: 300000\n                  description: |-\n                    Run commands in a PowerShell shell\n                    * When invoking this tool, the contents of the \"command\" parameter does NOT need to be XML-escaped.\n                    * You don't have access to the internet via this tool.\n                    * State is persistent across command calls and discussions with the user.\n                    * Use native Windows paths (C:\\...) and $env:NAME variables; this is PowerShell, not bash.\n                    * Please avoid commands that may produce a very large amount of output.\n                    * Please run long lived commands in the background, e.g. 'Start-Job' or start a server with Start-Process.\n\n# Agent preset ptc: one `@deepseek-ai/dsh-agent-preset` declaration inserted\n# after the web patch. Edits saved from the Web editor override this row's\n# `config.plugins` by id from the profile patch.\n- insert:\n    - id: preset-ptc\n      name: '@deepseek-ai/dsh-agent-preset'\n      config:\n        id: ptc\n        order: 2\n        plugins:\n          - id: persona\n            name: '@deepseek-ai/dsh-persona'\n            config:\n              suffix: Your working directory is {{cwd}}.\n              prefix: You are a coding agent powered by the {{model}} model.\n          - id: agent-instructions\n            name: '@deepseek-ai/dsh-agent-instructions'\n            config:\n              maxBytes: 65536\n          - id: tool-bash\n            name: '@deepseek-ai/dsh-tool-bash'\n            disabled: !!js process.platform === 'win32'\n          - id: tool-pwsh\n            name: '@deepseek-ai/dsh-tool-pwsh'\n            disabled: !!js process.platform !== 'win32'\n          - id: tool-fs\n            name: '@deepseek-ai/dsh-tool-fs'\n          - id: tool-fs-search\n            name: '@deepseek-ai/dsh-tool-fs-search'\n            config:\n              sampleOverCapGlobResults: false\n          - id: tool-jobs\n            name: '@deepseek-ai/dsh-tool-jobs'\n          - id: skill-filesystem\n            name: '@deepseek-ai/dsh-skill-filesystem'\n          - id: tool-skill\n            name: '@deepseek-ai/dsh-tool-skill'\n          - id: command-goal\n            name: '@deepseek-ai/dsh-command-goal'\n          - id: tool-goal\n            name: '@deepseek-ai/dsh-tool-goal'\n          - id: planning\n            name: cordis:group\n            group: true\n            isolate:\n              planMode: true\n            config:\n              - id: plan-mode\n                name: '@deepseek-ai/dsh-plan-mode'\n                config:\n                  section: |\n                    You are in plan mode. Stay in plan mode until exit_plan_mode succeeds or the user switches the session mode. Imperative language to implement changes means plan the implementation, not execute it. A user's conversational agreement — including an answer confirming something you asked — approves nothing and does not end plan mode; fold the confirmed decision into the plan and submit it through exit_plan_mode.\n\n                    Explore first. Use non-mutating reads, searches, static analysis, and checks to ground the plan in the actual repository. Do not edit or write files, change configuration, run formatters or code generation that rewrites tracked files, commit, or otherwise carry out the plan. Prefer existing functions and patterns over new machinery.\n\n                    The tool catalog stays the same across modes for request-cache stability. These plan-mode rules override any later tool description or guidance that suggests using mutation tools; those tools remain listed to keep the tool catalog unchanged. Do not use todo_write to track this planning phase: it tracks implementation after an approved plan, while the plan itself belongs in exit_plan_mode.\n\n                    Resolve discoverable facts by inspection. Use ask_user_question only for user-owned choices or material ambiguity that inspection cannot answer. Do not ask the user where code lives or how current behavior works when you can find out.\n\n                    Make the plan decision-complete: state the goal and success criteria; group implementation changes by subsystem; identify public API, schema, and data-flow changes; cover edge cases, failure modes, tests, acceptance criteria, and explicit assumptions. Keep it concise enough to review but detailed enough that another engineer can implement it without making design decisions.\n\n                    When ready, call exit_plan_mode with the complete plan markdown, starting with a # title. Make exit_plan_mode the only and final tool call in that assistant response: it presents the plan for approval, and implementation begins only in a later step after approval. Do not paste the final plan as a plain reply or ask \"should I proceed?\" through prose or ask_user_question. If review rejects it, incorporate the feedback and present again. If the review channel is unavailable or aborted, stay in plan mode and ask the user to switch modes manually; do not proceed with implementation.\n          - id: compaction\n            name: cordis:group\n            group: true\n            isolate:\n              compaction: true\n              toolResultPruner: true\n            config:\n              - id: compaction-basic\n                name: '@deepseek-ai/dsh-compaction-basic'\n              - id: command-compact\n                name: '@deepseek-ai/dsh-command-compact'\n              - id: tool-result-pruner\n                name: '@deepseek-ai/dsh-compaction-tool-result-pruner'\n                config:\n                  thresholdChars: 8192\n                  headChars: 4096\n                  tailChars: 1024\n          - id: delegation\n            name: cordis:group\n            group: true\n            isolate:\n              workflowEngine: true\n            config:\n              - id: tool-subagent-control\n                name: '@deepseek-ai/dsh-tool-subagent-control'\n              - id: tool-subagent-list-agents\n                name: '@deepseek-ai/dsh-tool-subagent-control/list-agents'\n              - id: tool-subagent\n                name: '@deepseek-ai/dsh-tool-subagent'\n                config:\n                  provider: spawn\n                  toolName: subagent\n                  modelSelectionSettings: true\n                  backgroundMode: continuable\n              - id: tool-subagent-fork\n                name: '@deepseek-ai/dsh-tool-subagent'\n                config:\n                  provider: fork\n                  toolName: subagent_fork\n                  backgroundMode: continuable\n              - id: tool-subagent-codex\n                name: '@deepseek-ai/dsh-tool-subagent'\n                disabled: true\n                config:\n                  provider: codex\n                  toolName: subagent_codex\n                  backgroundMode: one-shot\n                  maxDepth: provider-managed\n              - id: tool-subagent-claude-code\n                name: '@deepseek-ai/dsh-tool-subagent'\n                disabled: true\n                config:\n                  provider: claude-code\n                  toolName: subagent_claude_code\n                  backgroundMode: one-shot\n                  maxDepth: provider-managed\n              - id: workflow-ptc\n                name: '@deepseek-ai/dsh-workflow-ptc'\n                disabled: true\n                config:\n                  provider: spawn\n              - id: tool-workflow\n                name: '@deepseek-ai/dsh-tool-workflow'\n                disabled: true\n              - id: tool-ralph\n                name: '@deepseek-ai/dsh-tool-ralph'\n                disabled: true\n                config:\n                  subagentProvider: spawn\n                  maxRounds: 64\n          - id: tool-ask-user\n            name: '@deepseek-ai/dsh-tool-ask-user'\n          - id: tool-todo\n            name: '@deepseek-ai/dsh-tool-todo'\n            config:\n              allowParallelInProgress: true\n          - id: tool-web\n            name: '@deepseek-ai/dsh-tool-web'\n            config:\n              fetch: true\n              searchTimeoutMs: 60000\n          - id: tool-presentation\n            name: '@deepseek-ai/dsh-agent-tool-presentation'\n            config:\n              mode: ptc\n          - id: present\n            name: '@deepseek-ai/dsh-tool-present'\n          - id: tool-plugin-manager\n            name: '@deepseek-ai/dsh-plugin-manager/tools'\n            disabled: true\n\n- insert:\n    - id: seektty-appearance\n      name: 'seektty/settings/appearance'\n\n- insert:\n    - id: seektty-behavior\n      name: 'seektty/settings/behavior'\n\n- insert:\n    - id: seektty-composer-history\n      name: 'seektty/settings/composer-history'\n\n- insert:\n    - id: seektty-welcome\n      name: 'seektty/settings/welcome'\n\n- insert:\n    - id: tui-plugin-marketplace\n      name: 'seektty/settings/marketplace'\n"
