      "path": "src/bin.ts",
      "content": "#!/usr/bin/env node\n\n/** Product launcher that provisions and boots the native dsh Profile. */\n\nimport { existsSync, readFileSync, realpathSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { dirname, join, resolve } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport crossSpawn from 'cross-spawn'\nimport {\n  DSH_COMPATIBILITY,\n  PACKAGE_NAME,\n  PACKAGE_VERSION,\n  defaultPluginSpec,\n  isVersionRequest,\n  launcherCopy,\n  launcherPrefersEnglish,\n  versionMessage,\n} from './dsh-compat.ts'\nimport {\n  type InstalledFacts,\n  type UpdatePlan,\n  DEFAULT_SCAN_TIMEOUT_MS,\n  exclusiveUpdatePlan,\n  parseDshCliVersion,\n  scanLatestVersions,\n  updateAdvice,\n  updatePlan,\n} from './version-scan.ts'\nimport { measureStartupSync } from './startup-trace.ts'\nimport {\n  dshPluginArgs,\n  dshPluginCommand,\n  pnpmCommand,\n  pnpmGvsRecoveryAdvice,\n  isPnpmGlobalVirtualStorePath,\n  withPnpmGvsCompatibility,\n} from './pnpm-compat.ts'\n\nconst LEGACY_PACKAGE_NAME = 'deepseek-tui'\nconst DEFAULT_SPEC = defaultPluginSpec(PACKAGE_VERSION)\nconst DSH_INSTALL_SPEC = `@deepseek-ai/dsh@${DSH_COMPATIBILITY.tested}`\n\nfunction resolveProfileDir(\n  name: string,\n  environment: NodeJS.ProcessEnv = process.env,\n): string {\n  if (\n    name === ''\n    || name === '.'\n    || name === '..'\n    || name === 'node_modules'\n    || name.includes('/')\n    || name.includes('\\\\')\n  ) {\n    throw new Error(`dsh: invalid profile name ${JSON.stringify(name)}`)\n  }\n  const configuredValue = Object.hasOwn(environment, 'DSH_HOME')\n    ? environment.DSH_HOME\n    : process.env.DSH_HOME\n  const configured = configuredValue?.trim()\n  const rawHome = configured === undefined || configured === '' ? join(homedir(), '.dsh') : configured\n  const expandedHome = rawHome === '~'\n    ? homedir()\n    : rawHome.startsWith('~/') || rawHome.startsWith('~\\\\')\n      ? join(homedir(), rawHome.slice(2))\n      : rawHome\n  return join(resolve(expandedHome), 'profiles', name)\n}\n\n/** True when the launcher should run the update flow instead of booting. */\nexport function isUpdateRequest(args: readonly string[]): boolean {\n  return args.includes('--update')\n}\n\n/** How the launcher follows the npm `latest` dist-tags for official dsh and SeekTTY. */\nexport type UpdateMode = 'auto' | 'check' | 'off'\n\n/**\n * Resolve the update policy. Default is auto. `SEEKTTY_UPDATE` wins over the\n * legacy `SEEKTTY_UPDATE_CHECK=0` off switch.\n */\nexport function updateMode(environment: NodeJS.ProcessEnv = process.env): UpdateMode {\n  const explicit = environment.SEEKTTY_UPDATE?.trim().toLowerCase()\n  if (explicit !== undefined && explicit !== '') {\n    if (explicit === '0' || explicit === 'off' || explicit === 'false' || explicit === 'manual') return 'off'\n    if (explicit === 'check' || explicit === 'notice') return 'check'\n    return 'auto'\n  }\n  return environment.SEEKTTY_UPDATE_CHECK?.trim() === '0' ? 'off' : 'auto'\n}\n\n/** True when a plugin spec is a local path, file URL, or link, not a release. */\nexport function isLocalPluginSpec(spec: string | undefined): boolean {\n  if (spec === undefined) return false\n  const value = spec.trim()\n  if (value === '') return false\n  if (/^(?:file:|link:)/iu.test(value)) return true\n  if (/^(?:git\\+|github:|gitlab:|bitbucket:|https?:|npm:)/iu.test(value)) return false\n  return value.startsWith('.') || value.startsWith('/') || /^[A-Za-z]:[\\\\/]/u.test(value)\n}\n\nfunction installedFacts(environment: NodeJS.ProcessEnv, profile = 'tui'): InstalledFacts {\n  const override = environment.SEEKTTY_SPEC?.trim() || environment.DEEPSEEK_TUI_SPEC?.trim() || ''\n  const installedSpec = profileManifest(profile, environment)?.dependencies?.[PACKAGE_NAME]\n  const dshPinned = (environment.DSH_BIN?.trim() ?? '') !== ''\n  return {\n    dshTested: DSH_COMPATIBILITY.tested,\n    dshInstalled: dshPinned ? undefined : internals.readInstalledDshVersion('dsh', environment),\n    seekttyVersion: PACKAGE_VERSION,\n    dshPinned,\n    seekttyPinned: override !== '' || isLocalPluginSpec(installedSpec),\n  }\n}\n\ninterface ProfileManifest {\n  readonly dependencies?: Readonly<Record<string, string>>\n}\n\nexport function launcherArgs(\n  args: readonly string[],\n  environment: NodeJS.ProcessEnv = process.env,\n): { profile: string; inner: string[] } {\n  let profile = 'tui'\n  const inner: string[] = []\n  for (let index = 0; index < args.length; index += 1) {\n    const argument = args[index]\n    if (argument === '--profile') {\n      const value = args[index + 1]\n      if (value === undefined || value.trim() === '') {\n        throw new Error(launcherCopy(\n          '--profile 需要一个 Profile 名称',\n          '--profile requires a Profile name',\n          launcherPrefersEnglish(environment),\n        ))\n      }\n      profile = value\n      index += 1\n      continue\n    }\n    if (argument?.startsWith('--profile=') === true) {\n      const value = argument.slice('--profile='.length)\n      if (value === '') {\n        throw new Error(launcherCopy(\n          '--profile 需要一个 Profile 名称',\n          '--profile requires a Profile name',\n          launcherPrefersEnglish(environment),\n        ))\n      }\n      profile = value\n      continue\n    }\n    if (argument !== undefined) inner.push(argument)\n  }\n  return { profile, inner }\n}\n\nfunction profileManifest(\n  profile: string,\n  environment: NodeJS.ProcessEnv = process.env,\n): ProfileManifest | undefined {\n  const manifestPath = join(resolveProfileDir(profile, environment), 'package.json')\n  if (!existsSync(manifestPath)) return undefined\n  const raw = readFileSync(manifestPath, 'utf8')\n  try {\n    return JSON.parse(raw) as ProfileManifest\n  } catch (error) {\n    const detail = error instanceof Error ? error.message : String(error)\n    const english = launcherPrefersEnglish(environment)\n    throw new Error([\n      launcherCopy(\n        `无法解析 Profile manifest ${manifestPath}：${detail}`,\n        `Cannot parse Profile manifest ${manifestPath}: ${detail}`,\n        english,\n      ),\n      launcherCopy(\n        '删除该文件后 deepseek 会重新初始化 Profile。',\n        'Delete that file and deepseek will re-initialize the Profile.',\n        english,\n      ),\n    ].join('\\n'))\n  }\n}\n\nfunction hasDependency(manifest: ProfileManifest | undefined, name: string): boolean {\n  return manifest?.dependencies?.[name] !== undefined\n}\n\nexport function installed(profile: string): boolean {\n  return hasDependency(profileManifest(profile), PACKAGE_NAME)\n}\n\n/** Spawn options that resolve PATHEXT shims on Windows and hide extra consoles. */\nexport const DSH_SPAWN_OPTIONS = { stdio: 'inherit' as const, windowsHide: true }\n\n/**\n * Env for `dsh --version`. Keep a normal subprocess environment so wrappers\n * that need HOME or NODE_OPTIONS still work. SeekTTY omits the caller's\n * explicit DSH_HOME; DSH_BIN is pinned and is not probed.\n */\nexport function dshVersionProbeEnv(environment: NodeJS.ProcessEnv): NodeJS.ProcessEnv {\n  const env = { ...process.env, ...environment }\n  delete env.DSH_HOME\n  return env\n}\n\n/** Replaceable spawn seam used by launcher tests. */\nexport const internals: {\n  spawnSync: (\n    command: string,\n    args: readonly string[],\n    options: typeof DSH_SPAWN_OPTIONS,\n  ) => { error?: Error | null; signal: NodeJS.Signals | null; status: number | null }\n  /**\n   * Read the installed Host version from PATH `dsh --version`.\n   * DSH_BIN is pinned and is not probed. SeekTTY only captures the command's\n   * version output; it does not inspect Profile or Session files itself.\n   */\n  readInstalledDshVersion: (command: string, environment: NodeJS.ProcessEnv) => string | undefined\n} = {\n  spawnSync: (command, args, options) => crossSpawn.sync(command, [...args], options),\n  readInstalledDshVersion: (command, environment) => {\n    try {\n      const result = crossSpawn.sync(command, ['--version'], {\n        encoding: 'utf8',\n        windowsHide: true,\n        timeout: DEFAULT_SCAN_TIMEOUT_MS,\n        env: dshVersionProbeEnv(environment),\n      })\n      if (result.error != null || result.status !== 0 || result.signal != null) return undefined\n      return parseDshCliVersion(`${result.stdout ?? ''}\\n${result.stderr ?? ''}`)\n    } catch {\n      return undefined\n    }\n  },\n}\n\nfunction missingDshMessage(command: string, english: boolean): string {\n  const installCommand = pnpmCommand(['add', '--global', DSH_INSTALL_SPEC])\n  return [\n    launcherCopy(\n      `${command} 未安装或不在 PATH 中。`,\n      `${command} is not installed or not on PATH.`,\n      english,\n    ),\n    launcherCopy(\n      `请先安装 DeepSeek Harness：${installCommand}`,\n      `Install DeepSeek Harness: ${installCommand}`,\n      english,\n    ),\n    launcherCopy(\n      '或设置 DSH_BIN 指向 dsh 可执行文件后重试。',\n      'Or set DSH_BIN to the dsh executable and retry.',\n      english,\n    ),\n  ].join('\\n')\n}\n\nfunction classifySpawnError(command: string, error: NodeJS.ErrnoException, english: boolean): Error {\n  if (error.code === 'ENOENT') return new Error(missingDshMessage(command, english))\n  return error\n}\n\nfunction realPathUsesPnpmGvs(path: string): boolean {\n  try {\n    return existsSync(path) && isPnpmGlobalVirtualStorePath(realpathSync(path))\n  } catch {\n    return false\n  }\n}\n\n/**\n * Detect a visible pnpm 11 GVS installation without probing or changing pnpm\n * configuration. The launcher module covers Profile/global SeekTTY installs;\n * explicit dsh paths and PNPM_HOME cover the stock Host installation.\n */\nexport function launcherUsesPnpmGvsLayout(\n  dsh: string,\n  environment: NodeJS.ProcessEnv = process.env,\n): boolean {\n  const candidates = [fileURLToPath(import.meta.url)]\n  if (dsh.includes('/') || dsh.includes('\\\\')) {\n    candidates.push(dsh, join(dirname(dsh), 'node_modules', '@deepseek-ai', 'dsh'))\n  }\n  const pnpmHome = environment.PNPM_HOME?.trim()\n  if (pnpmHome !== undefined && pnpmHome !== '') {\n    candidates.push(join(pnpmHome, 'node_modules', '@deepseek-ai', 'dsh'))\n  }\n  return candidates.some(realPathUsesPnpmGvs)\n}\n\nexport function run(command: string, args: readonly string[]): number {\n  const result = internals.spawnSync(command, [...args], DSH_SPAWN_OPTIONS)\n  const english = launcherPrefersEnglish(process.env)\n  if (result.error != null) throw classifySpawnError(command, result.error, english)\n  if (result.signal === 'SIGINT' || result.signal === 'SIGTERM') return 130\n  if (result.signal !== null) {\n    throw new Error(launcherCopy(\n      `${command} 被信号 ${result.signal} 终止`,\n      `${command} was terminated by signal ${result.signal}`,\n      english,\n    ))\n  }\n  return result.status ?? 1\n}\n\nexport function launch(\n  args: readonly string[],\n  environment: NodeJS.ProcessEnv = process.env,\n  execute: (command: string, args: readonly string[]) => number = run,\n  write: (chunk: string) => void = chunk => { process.stdout.write(chunk) },\n  writeError: (chunk: string) => void = chunk => { process.stderr.write(chunk) },\n): number {\n  if (isVersionRequest(args)) {\n    write(versionMessage({\n      name: PACKAGE_NAME,\n      version: PACKAGE_VERSION,\n      compatibility: DSH_COMPATIBILITY,\n    }, launcherPrefersEnglish(environment)))\n    return 0\n  }\n  const { profile, inner } = launcherArgs(args, environment)\n  const dsh = environment.DSH_BIN?.trim() || 'dsh'\n  const stderr = writeError\n  let manifest = measureStartupSync('launcher-manifest', () => profileManifest(profile, environment), environment, stderr)\n  const recoverySpec = environment.SEEKTTY_SPEC?.trim()\n    || environment.DEEPSEEK_TUI_SPEC?.trim()\n    || manifest?.dependencies?.[PACKAGE_NAME]\n    || DEFAULT_SPEC\n  let compatibilityHintWritten = false\n  const finish = (status: number): number => {\n    if (status === 0 || compatibilityHintWritten || !launcherUsesPnpmGvsLayout(dsh, environment)) return status\n    compatibilityHintWritten = true\n    writeError(`${pnpmGvsRecoveryAdvice({\n      english: launcherPrefersEnglish(environment),\n      profile,\n      dshSpec: DSH_INSTALL_SPEC,\n      pluginSpec: recoverySpec,\n    })}\\n`)\n    return status\n  }\n  if (hasDependency(manifest, LEGACY_PACKAGE_NAME)) {\n    const status = execute(dsh, dshPluginArgs(profile, ['remove', LEGACY_PACKAGE_NAME]))\n    if (status !== 0) return finish(status)\n    manifest = measureStartupSync('launcher-manifest', () => profileManifest(profile, environment), environment, stderr)\n  }\n  if (!hasDependency(manifest, PACKAGE_NAME)) {\n    const spec = environment.SEEKTTY_SPEC?.trim() || environment.DEEPSEEK_TUI_SPEC?.trim() || DEFAULT_SPEC\n    const status = measureStartupSync(\n      'plugin-add',\n      () => execute(dsh, dshPluginArgs(profile, ['add', spec])),\n      environment,\n      stderr,\n    )\n    if (status !== 0) return finish(status)\n  }\n  return finish(execute(dsh, ['--profile', profile, ...inner]))\n}\n\nasync function applyUpdatePlan(\n  plan: UpdatePlan,\n  profile: string,\n  facts: InstalledFacts,\n  english: boolean,\n  environment: NodeJS.ProcessEnv,\n  execute: (command: string, args: readonly string[]) => number,\n  write: (chunk: string) => void,\n  options: { readonly announcePinnedDsh: boolean; readonly announceCurrentSeektty: boolean },\n): Promise<number> {\n  const exclusive = exclusiveUpdatePlan(plan)\n  if (options.announcePinnedDsh && facts.dshPinned) {\n    write(launcherCopy(\n      'DSH_BIN 已固定 dsh 可执行文件，跳过 dsh 更新。\\n',\n      'DSH_BIN pins the dsh executable; skipping the dsh update.\\n',\n      english,\n    ))\n  }\n  if (exclusive.dshSpec !== undefined) {\n    const command = pnpmCommand(['add', '--global', exclusive.dshSpec])\n    write(launcherCopy(`更新 dsh：${command}\\n`, `Updating dsh: ${command}\\n`, english))\n    let status: number\n    try {\n      status = execute('pnpm', withPnpmGvsCompatibility(['add', '--global', exclusive.dshSpec]))\n    } catch {\n      write(launcherCopy(\n        `pnpm 不可用。请手动运行：${command}\\n`,\n        `pnpm is unavailable. Run manually: ${command}\\n`,\n        english,\n      ))\n      return 1\n    }\n    if (status !== 0) return status\n  }\n  if (exclusive.seekttySpec !== undefined) {\n    const dsh = environment.DSH_BIN?.trim() || 'dsh'\n    const command = dshPluginCommand(profile, ['add', exclusive.seekttySpec])\n    write(launcherCopy(`更新 SeekTTY：${command}\\n`, `Updating SeekTTY: ${command}\\n`, english))\n    const status = execute(dsh, dshPluginArgs(profile, ['add', exclusive.seekttySpec]))\n    if (status !== 0) return status\n  } else if (options.announceCurrentSeektty) {\n    write(facts.seekttyPinned\n      ? launcherCopy(\n        'SeekTTY 已由本地路径、link 或 SEEKTTY_SPEC 固定，跳过 SeekTTY 更新。\\n',\n        'SeekTTY is pinned by a local path, link, or SEEKTTY_SPEC; skipping the SeekTTY update.\\n',\n        english,\n      )\n      : launcherCopy(\n        `SeekTTY 已是最新版本（${PACKAGE_VERSION}）。\\n`,\n        `SeekTTY is already the latest version (${PACKAGE_VERSION}).\\n`,\n        english,\n      ))\n  }\n  return 0\n}\n\n/**\n * `deepseek --update`: same permit gate as auto. At most one component.\n * Future/gap Hosts are printed and never installed.\n */\nexport async function runUpdate(\n  args: readonly string[],\n  environment: NodeJS.ProcessEnv = process.env,\n  execute: (command: string, args: readonly string[]) => number = run,\n  write: (chunk: string) => void = chunk => { process.stdout.write(chunk) },\n  scan: typeof scanLatestVersions = scanLatestVersions,\n): Promise<number> {\n  const english = launcherPrefersEnglish(environment)\n  const { profile } = launcherArgs(args.filter(argument => argument !== '--update'), environment)\n  write(launcherCopy('正在检查 dsh 与 SeekTTY 的最新版本…\\n', 'Checking the latest dsh and SeekTTY versions…\\n', english))\n  const facts = installedFacts(environment, profile)\n  const result = await scan()\n  if (result.dshLatest === undefined && result.seekttyLatest === undefined) {\n    write(launcherCopy(\n      '无法访问 npm Registry，请检查网络后重试。\\n',\n      'Could not reach the npm Registry. Check the network and retry.\\n',\n      english,\n    ))\n    return 1\n  }\n  const plan = updatePlan(result, facts)\n  if (plan.dshSpec === undefined && plan.seekttySpec === undefined) {\n    const lines = updateAdvice(result, facts, english)\n    if (lines.length > 0) write(`${lines.join('\\n')}\\n`)\n  }\n  return applyUpdatePlan(plan, profile, facts, english, environment, execute, write, {\n    announcePinnedDsh: true,\n    announceCurrentSeektty: true,\n  })\n}\n\n/**\n * Default launch policy: fetch the npm `latest` dist-tags for official dsh and\n * SeekTTY, then apply them. Offline and install failures never block boot.\n */\nexport async function maybeAutoUpdate(\n  args: readonly string[],\n  environment: NodeJS.ProcessEnv = process.env,\n  execute: (command: string, args: readonly string[]) => number = run,\n  write: (chunk: string) => void = chunk => { process.stderr.write(chunk) },\n  scan: typeof scanLatestVersions = scanLatestVersions,\n): Promise<void> {\n  if (updateMode(environment) !== 'auto') return\n  if (isVersionRequest(args) || isUpdateRequest(args)) return\n  try {\n    const english = launcherPrefersEnglish(environment)\n    const { profile } = launcherArgs(args, environment)\n    const facts = installedFacts(environment, profile)\n    const result = await scan()\n    const plan = updatePlan(result, facts)\n    if (plan.dshSpec === undefined && plan.seekttySpec === undefined) return\n    await applyUpdatePlan(plan, profile, facts, english, environment, execute, write, {\n      announcePinnedDsh: false,\n      announceCurrentSeektty: false,\n    })\n  } catch {\n    // 静默：自动更新绝不能挡住启动。\n  }\n}\n\n/**\n * Passive post-session check used by `SEEKTTY_UPDATE=check`.\n * Network failures are silent.\n */\nexport async function postSessionUpdateNotice(\n  environment: NodeJS.ProcessEnv = process.env,\n  write: (chunk: string) => void = chunk => { process.stderr.write(chunk) },\n  scan: typeof scanLatestVersions = scanLatestVersions,\n): Promise<void> {\n  if (updateMode(environment) !== 'check') return\n  try {\n    const result = await scan()\n    const lines = updateAdvice(result, installedFacts(environment), launcherPrefersEnglish(environment))\n    if (lines.length > 0) write(`${lines.join('\\n')}\\n`)\n  } catch {\n    // 静默：更新提示绝不能影响正常退出。\n  }\n}\n\nfunction directInvocation(): boolean {\n  const entry = process.argv[1]\n  if (entry === undefined) return false\n  try {\n    return realpathSync(entry) === realpathSync(fileURLToPath(import.meta.url))\n  } catch {\n    return false\n  }\n}\n\nif (directInvocation()) {\n  const args = process.argv.slice(2)\n  try {\n    if (isUpdateRequest(args)) {\n      process.exitCode = await runUpdate(args)\n    } else {\n      await maybeAutoUpdate(args)\n      process.exitCode = launch(args)\n      if (!isVersionRequest(args) && process.stderr.isTTY === true) {\n        await postSessionUpdateNotice()\n      }\n    }\n  } catch (error) {\n    process.stderr.write(`deepseek: ${error instanceof Error ? error.message : String(error)}\\n`)\n    process.exitCode = 1\n  }\n}\n"
    },
    {
      "path": "src/client/capabilities.ts",
      "content": "/** Platform-neutral TUI actions over authoritative Harness Client faces. */\n\nimport { mkdir, open, readFile, stat, unlink } from 'node:fs/promises'\nimport { basename, dirname, resolve } from 'node:path'\nimport { getImageDimensions } from '@mariozechner/pi-tui'\nimport { autoPermissionPresentation } from './auto-review-presentation.ts'\nimport type {\n  IApiClient,\n  JobView,\n  ModelReasoningEffort,\n  ModelSelection,\n  PromptContentPart,\n  QuestionResponsePayload,\n  SessionId,\n  SessionModels,\n  SkillEntry,\n  SubagentAddress,\n  WorkspaceId,\n  WorkspaceView,\n} from '@deepseek-ai/dsh-api-remotes/node-client'\nimport type { ConnectionHandle, SubagentListEntry } from '@deepseek-ai/dsh-client-connection/node-client'\n// Pull the generated Remote namespace and forwarded-event declarations into\n// this Client program. Runtime values still come from the mounted assembly.\nimport type {} from '@deepseek-ai/dsh-api-remotes/node-client'\nimport type {\n  AssistantMessageNode,\n  ConversationSnapshot,\n  PendingInteraction,\n  PendingWait,\n  SessionFace,\n  SessionSearchResultItem,\n  SessionSummary,\n} from '@deepseek-ai/dsh-client-runtime/node-client'\nimport type {\n  MessageFeedbackItem,\n  MessageFeedbackRating,\n  MessageFeedbackVersion,\n} from '@deepseek-ai/dsh-message-feedback/types'\nimport type { TrajectorySnapshot } from '@deepseek-ai/dsh-client-ui-trajectory/projection'\nimport { TuiSettingsConflictError } from '@deepseek-ai/dsh-tui-protocol'\nimport type { TuiManagementBridge } from './management.ts'\nimport type { TuiClientContext } from './context.ts'\nimport { copyTargets } from './copy-content.ts'\nimport { flattenProducedFiles, type ProducedFileGroup } from './produced-files.ts'\nimport { explainFailure, withRunningRetry } from './error-advice.ts'\nimport { ui, uiLocale } from './locale.ts'\nimport { resolveHarnessUserPath } from './workspace-path.ts'\nimport type { ProviderApi } from './provider-config.ts'\nimport { mergeClarifyCatalog } from './clarify-shell.ts'\nimport { probeClarifyRemote } from './clarify-remote.ts'\nimport {\n  readAuxiliaryUsageSnapshot,\n  type AuxiliaryUsageBuckets,\n} from './auxiliary-runtime-remote.ts'\nimport {\n  createSubagentPresentationCapabilities,\n  type SubagentPresentationCapabilities,\n} from './subagent-presentation.ts'\nimport {\n  RootSessionCatalogProjector,\n  projectRootSessions,\n  rootCatalogRevision,\n  type RootCatalogResult,\n} from './root-session-catalog.ts'\nimport { SessionBrowserController } from './session-browser.ts'\nimport { HostFileController, containedHostPath, type HostFileOptions } from './host-file-controller.ts'\nimport { ArtifactViewController } from './artifact-view.ts'\nimport { McpResourceController } from './mcp-resource-view.ts'\nimport { TeamBoardController } from './team-view.ts'\nimport { ScheduleController } from './schedule-view.ts'\nimport { SubagentCatalogController, type SubagentDescendantPort } from './subagent-catalog-view.ts'\nimport { ContinuedQuestionController, type ContinuedQuestionSource } from './continued-question-view.ts'\nimport type { OptionalViewSource } from './optional-view-lifetime.ts'\nimport { OptionalViewLifetime } from './optional-view-lifetime.ts'\nimport { ModelInformationController, type ModelInformation } from './model-information.ts'\nimport { AccountHandoffController } from './account-handoff.ts'\nimport { PACKAGE_VERSION } from '../dsh-compat.ts'\nimport { configuredModelEvidence } from './configured-model-evidence.ts'\nimport { ManagementInterrupted } from './management-lifetime.ts'\nimport { FileAttachmentController, type StagedFile, type FileReferenceCandidate } from './file-attachments.ts'\n\n/** A command shown by the terminal's merged slash directory. */\nexport interface TuiCommandCandidate {\n  readonly name: string\n  readonly description: string\n  readonly argumentHint?: string\n  readonly source: 'TUI' | 'Host' | 'Host + TUI' | 'Skill'\n  readonly behavior: 'local' | 'host' | 'skill'\n}\n\n/**\n * Compatible names that still execute, but stay out of `/`, Ctrl+P, and help.\n * Hidden name → visible canonical name.\n */\nexport const TUI_HIDDEN_COMMAND_ALIASES = Object.freeze({\n  resume: 'sessions',\n  plugins: 'plugin',\n  quit: 'exit',\n} as const)\n\n/**\n * Map a typed command token to the catalog name used for lookup.\n * @param name - token without a leading slash.\n */\nexport function canonicalTuiCommandName(name: string): string {\n  return TUI_HIDDEN_COMMAND_ALIASES[name as keyof typeof TUI_HIDDEN_COMMAND_ALIASES] ?? name\n}\n\n/**\n * Visible TUI names plus hidden aliases that must keep occupying the merged catalog.\n * Host or Skill entries with these names must not steal typed `/resume` `/plugins` `/quit`.\n */\nexport function reservedTuiCatalogNames(): ReadonlySet<string> {\n  return new Set([\n    ...Object.keys(TUI_HIDDEN_COMMAND_ALIASES),\n    ...tuiCommands().map(command => command.name),\n  ])\n}\n\n/** One selectable Agent Preset from the Host directory. */\nexport interface TuiModeOption {\n  readonly id: string\n  readonly label: string\n  readonly description?: string\n  readonly current: boolean\n  readonly isDefault: boolean\n  readonly disabledReason?: string\n}\n\n/** One Provider/model route and its adapter-owned reasoning choices. */\nexport interface TuiModelOption {\n  readonly id: string\n  readonly label: string\n  readonly description: string\n  readonly selection: ModelSelection\n  readonly efforts: readonly ModelReasoningEffort[]\n  readonly defaultEffort?: string\n  readonly currentEffort?: string\n  readonly current: boolean\n}\n\n/** One permission option projected by the Host. */\nexport interface TuiPermissionOption {\n  readonly id: string\n  readonly label: string\n  readonly description?: string\n  readonly current: boolean\n  readonly needsConfirmation: boolean\n}\n\n/** Current session binding, resolved from the Runtime selection. */\nexport interface TuiActiveSession {\n  readonly sessionId: SessionId\n  readonly session: SessionFace\n  readonly summary: SessionSummary\n  readonly workspacePath: string\n  readonly workspaceId?: WorkspaceId\n}\n\n/** Top-strip facts; business values remain owned by the Host and Runtime. */\nexport interface TuiHeaderFacts {\n  readonly hostVersion: string\n  readonly nodeVersion: string\n  readonly platform: NodeJS.Platform\n  readonly architecture: string\n  readonly profile: string\n  readonly workspace: string\n  readonly session: string\n  readonly mode: string\n  readonly reasoning?: string\n  readonly model: string\n  readonly permission: string\n  readonly running: boolean\n  readonly context?: string\n  /** Epoch ms when the current turn started running; absent while idle. */\n  readonly runningSince?: number\n  /** Whether the context row should show a live elapsed clock. */\n  readonly statusElapsed?: boolean\n}\n\n/** Human-readable whole-session figures derived from registered projections. */\nexport interface TuiSessionStatistics {\n  readonly lines: readonly string[]\n  readonly context?: string\n}\n\n/** Optional whole-Session usage with explicit provenance from auxiliary-runtime. */\nexport interface TuiAuxiliaryUsageStatistics {\n  readonly lines: readonly [string, string, string]\n}\n\n/** Temporary image bytes waiting for the next Harness prompt admission. */\nexport interface TuiDraftAttachment {\n  readonly path: string\n  readonly name: string\n  readonly mediaType: 'image/png' | 'image/jpeg' | 'image/gif' | 'image/webp'\n  readonly data: string\n  readonly bytes: number\n  readonly width?: number\n  readonly height?: number\n}\n\n/** One dynamic tool schema recorded on the newest ordinary model request. */\nexport interface TuiToolOption {\n  readonly name: string\n  readonly description: string\n  readonly parameters: Readonly<Record<string, unknown>>\n}\n\n/** One direct child row paired with the exact Harness continuation address. */\nexport interface TuiSubagentOption {\n  readonly entry: SubagentListEntry\n  readonly address?: SubagentAddress\n  readonly totalTokens?: number\n  readonly durationMs?: number\n}\n\n/** Assistant message eligible for the Harness message-feedback sidecar. */\nexport interface TuiFeedbackTarget {\n  readonly message: AssistantMessageNode\n  readonly preview: string\n  readonly feedback?: MessageFeedbackItem\n}\n\n/** Result of saving one native Harness Session-log export. */\nexport interface TuiExportResult {\n  readonly path: string\n  readonly bytes: number\n  readonly mediaType: string\n  readonly includeDescendants: boolean\n}\n\ninterface PermissionSelectValue {\n  readonly currentValue: string\n  readonly options: readonly {\n    readonly value: string\n    readonly name: string\n    readonly description?: string\n  }[]\n}\n\ninterface ImageLimits {\n  readonly maxImageBytes: number\n  readonly maxImagesPerMessage: number\n  readonly maxMessageImageBytes: number\n  readonly maxImagePixels: number\n  readonly maxImageDimension?: number\n  readonly mediaTypes: readonly string[]\n}\n\ninterface HostCommandDescriptor {\n  readonly name: string\n  readonly description: string\n  readonly input?: { readonly hint: string }\n}\n\nconst SAFE_PERMISSION_PRESETS = new Set(['read-only', 'workspace-write'])\nconst FULL_ACCESS_PRESET = 'danger-full-access'\n// These remain Host-owned commands. The terminal adds a confirmation/selector\n// before dispatch, but does not register a second command with the same name.\nconst HOST_COMMAND_DECORATORS = new Set(['permission', 'feedback'])\nconst HOST_COMMAND_FUNCTIONS = new Map<string, { readonly zh: string; readonly en: string }>([\n  ['permission', { zh: '切换权限', en: 'Switch permission' }],\n  ['feedback', { zh: '提交会话反馈', en: 'Submit session feedback' }],\n  ['plan', { zh: '开启或关闭计划模式', en: 'Enable or disable plan mode' }],\n  ['goal', { zh: '管理当前目标', en: 'Manage current goal' }],\n  ['compact', { zh: '压缩当前会话上下文', en: 'Compact current session context' }],\n])\nconst HOST_COMMAND_ARGUMENT_HINTS = new Map<string, { readonly zh: string; readonly en: string }>([\n  ['permission', { zh: '[权限]', en: '[permission]' }],\n  ['feedback', { zh: '[内容]', en: '[text]' }],\n])\n\nexport function shortFunctionDescription(description: string, fallback: string): string {\n  const normalized = description.replace(/\\s+/gu, ' ').trim()\n  if (normalized === '') return fallback\n  const firstSentence = normalized.split(/[。；！？\\n]/u, 1)[0]?.trim() || fallback\n  const characters = Array.from(firstSentence)\n  return characters.length <= 48 ? firstSentence : `${characters.slice(0, 48).join('')}…`\n}\n\n/** TUI-owned product commands available in the terminal Surface. */\nexport function tuiCommands(): readonly TuiCommandCandidate[] {\n  return Object.freeze([\n    { name: 'new', description: ui('新建会话', 'New session'), source: 'TUI', behavior: 'local' },\n    { name: 'sessions', description: ui('查看或搜索会话', 'View or search sessions'), argumentHint: ui('[active|all|archived|搜索词]', '[active|all|archived|query]'), source: 'TUI', behavior: 'local' },\n    { name: 'model', description: ui('切换 Provider 和模型', 'Switch Provider and model'), source: 'TUI', behavior: 'local' },\n    { name: 'effort', description: ui('切换当前模型的推理强度', 'Change current model reasoning effort'), source: 'TUI', behavior: 'local' },\n    { name: 'mode', description: ui('切换模式', 'Switch mode'), source: 'TUI', behavior: 'local' },\n    { name: 'permission', description: ui('切换权限', 'Switch permission'), argumentHint: ui('[权限]', '[permission]'), source: 'Host + TUI', behavior: 'local' },\n    { name: 'workspace', description: ui('管理工作区', 'Manage workspaces'), argumentHint: ui('[子命令|路径]', '[subcommand|path]'), source: 'TUI', behavior: 'local' },\n    { name: 'display', description: ui('工作过程四种显示模式', 'Four work-process display modes'), source: 'TUI', behavior: 'local' },\n    { name: 'processes', description: ui('展开或折叠当前工作过程', 'Expand or collapse current processes'), source: 'TUI', behavior: 'local' },\n    { name: 'model-info', description: ui('查看模型能力信息', 'Inspect model capability information'), source: 'TUI', behavior: 'local' },\n    { name: 'account', description: ui('官方账号与登录', 'Official account and sign-in'), source: 'TUI', behavior: 'local' },\n    { name: 'speech', description: ui('选择 WAV 转写并确认插入草稿（实验性）', 'Transcribe a WAV and confirm draft insertion (experimental)'), argumentHint: '[wav]', source: 'TUI', behavior: 'local' },\n    { name: 'input-activities', description: ui('运行已安装的输入插件（仅插入草稿）', 'Run an installed input activity (draft insertion only)'), source: 'TUI', behavior: 'local' },\n    { name: 'rename', description: ui('重命名当前会话', 'Rename current session'), argumentHint: ui('<标题>', '<title>'), source: 'TUI', behavior: 'local' },\n    { name: 'fork', description: ui('从当前会话创建分支', 'Fork current session'), source: 'TUI', behavior: 'local' },\n    { name: 'archive', description: ui('归档当前会话', 'Archive current session'), source: 'TUI', behavior: 'local' },\n    { name: 'export', description: ui('导出当前会话', 'Export current session'), argumentHint: ui('[md] [路径]', '[md] [path]'), source: 'TUI', behavior: 'local' },\n    { name: 'copy', description: ui('复制最后一条回复', 'Copy last response'), argumentHint: '[pick|code]', source: 'TUI', behavior: 'local' },\n    { name: 'profile', description: ui('管理 Profile', 'Manage Profiles'), argumentHint: '[list|switch|create|copy]', source: 'TUI', behavior: 'local' },\n    { name: 'language', description: ui('切换界面语言', 'Switch interface language'), argumentHint: '[auto|zh|en]', source: 'TUI', behavior: 'local' },\n    { name: 'theme', description: ui('切换界面或独立代码主题', 'Switch interface or code theme'), argumentHint: '[dark|light|code|use|edit|palette|import|export|delete]', source: 'TUI', behavior: 'local' },\n    { name: 'welcome', description: ui('配置 Fastfetch 风格欢迎页', 'Configure the Fastfetch-style welcome page'), argumentHint: '[refresh|reset]', source: 'TUI', behavior: 'local' },\n    { name: 'queue', description: ui('管理排队消息', 'Manage que